CREATE TABLE stock (id INTEGER PRIMARY KEY, available INTEGER NOT NULL CHECK(available>=0));
INSERT INTO stock VALUES(1,10);
CREATE TABLE orders (
 id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, currency TEXT NOT NULL,
 amount INTEGER NOT NULL, state TEXT NOT NULL, expires INTEGER NOT NULL,
 shipping TEXT, total INTEGER, checkout_id TEXT UNIQUE, paid_charge TEXT UNIQUE
);
CREATE TABLE receipts (
 charge TEXT PRIMARY KEY, provider_charge TEXT NOT NULL, payload TEXT NOT NULL,
 user_id INTEGER NOT NULL, total INTEGER NOT NULL, currency TEXT NOT NULL,
 details TEXT NOT NULL, status TEXT NOT NULL
);

CREATE TABLE updates (id INTEGER PRIMARY KEY, response TEXT NOT NULL);
CREATE TABLE send_clock (id INTEGER PRIMARY KEY, attempted_at INTEGER NOT NULL);
INSERT INTO send_clock VALUES(1,0);
CREATE TABLE outbox (
 id INTEGER PRIMARY KEY AUTOINCREMENT, event_key TEXT NOT NULL UNIQUE,
 method TEXT NOT NULL, payload TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'pending', due INTEGER NOT NULL,
 attempts INTEGER NOT NULL DEFAULT 0, message_id INTEGER, error_code INTEGER
);

SELECT id,state,total,checkout_id,paid_charge FROM orders ORDER BY rowid DESC LIMIT 20;
SELECT charge,provider_charge,status FROM receipts WHERE status='review';
SELECT id,event_key,state,error_code FROM outbox WHERE state<>'sent';
